     2	
     3	/**
     4	 * Inbox list with read/unread affordances.
     5	 */
     6	import Link from "next/link";
     7	import { Button } from "@/components/ui/button";
     8	import { EmptyState } from "@/components/ui/empty-state";
     9	import { cn } from "@/lib/cn";
    10	import { formatRelative } from "@/lib/date";
    11	import type { NotificationId } from "@/types/common";
    12	import type { Notification } from "@/types/notification";
    13	import type { ReactElement } from "react";
    14	
    15	export type NotificationListProps = {
    16	  notifications: readonly Notification[];
    17	  onMarkRead: (id: NotificationId) => void;
    18	  onMarkAllRead: () => void;
    19	};
    20	
    21	/** Unread first, then newest first — the inbox ordering people expect. */
    22	export function orderInbox(
    23	  notifications: readonly Notification[],
    24	): readonly Notification[] {
    25	  return [...notifications].sort((a, b) => {
    26	    const byRead = Number(a.readAt !== null) - Number(b.readAt !== null);
    27	    if (byRead !== 0) return byRead;
    28	    return b.createdAt.localeCompare(a.createdAt);
    29	  });
    30	}
    31	
    32	export function NotificationList(
    33	  props: NotificationListProps,
    34	): ReactElement | null {
    35	  const { notifications, onMarkRead, onMarkAllRead } = props;
    36	
    37	  if (notifications.length === 0) {
    38	    return (
    39	      <EmptyState
    40	        title="You are all caught up"
    41	        description="Assignments, mentions and status changes land here."
    42	      />
    43	    );
    44	  }
    45	
    46	  const ordered = orderInbox(notifications);
    47	  const unread = ordered.filter((n) => n.readAt === null).length;
    48	
    49	  return (
    50	    <section className="notification-list space-y-2">
    51	      <div className="flex items-center justify-between">
    52	        <span className="text-sm text-neutral-500">{unread} unread</span>
    53	        <Button
    54	          variant="ghost"
    55	          size="sm"
    56	          disabled={unread === 0}
    57	          onClick={onMarkAllRead}
    58	        >
    59	          Mark all read
    60	        </Button>
    61	      </div>
    62	
    63	      <ul className="divide-y">
    64	        {ordered.map((notification) => (
    65	          <li
    66	            key={notification.id}
    67	            className={cn(
    68	              "flex items-start justify-between gap-3 py-2",
    69	              notification.readAt === null && "bg-indigo-50/50",
    70	            )}
    71	          >
    72	            <Link href={notification.href} className="min-w-0 flex-1">
    73	              <span className="block text-sm font-medium">
    74	                {notification.title}
    75	              </span>
    76	              <span className="block text-sm text-neutral-600">
    77	                {notification.body}
    78	              </span>
    79	              <span className="block text-xs text-neutral-500">
    80	                {formatRelative(notification.createdAt)}
    81	              </span>
    82	            </Link>
    83	
    84	            {notification.readAt === null ? (
    85	              <Button
    86	                variant="ghost"
    87	                size="sm"
    88	                onClick={() => onMarkRead(notification.id)}
    89	              >
    90	                Mark read
    91	              </Button>
    92	            ) : null}
    93	          </li>
    94	        ))}
    95	      </ul>
    96	    </section>
    97	  );
    98	}
