/**
 * Stamps one notification as read. Pass `recipientId` to make the write
 * refuse rows that belong to someone else; the digest job omits it because it
 * acts for the system. Returns `null` when no row matched.
 */
export async function markRead(
  orgId: OrgId,
  notificationId: NotificationId,
  at: IsoTimestamp,
  recipientId?: UserId,
): Promise<Notification | null> {
  const row = getDb()
    .update(notifications)
    .set({ readAt: at, updatedAt: at })
    .where(
      and(
        ...compact(
          orgPredicate(notifications.orgId, orgId),
          eq(notifications.id, notificationId),
          recipientId === undefined
            ? undefined
            : eq(notifications.recipientId, recipientId),
        ),
      ),
    )
    .returning()
    .get();

  return row ? toNotification(row) : null;
}

