/**
 * Private helpers that turn ids into the in-app paths alerts and search hits link to.
 *
 * The route shapes come from `@/lib/url`; this module only looks up the slugs and issue numbers those shapes need. A target that no longer exists resolves to `null`, so callers drop the link rather than ship a dead one.
 */
import { issuePath, projectPath } from "@/lib/url";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
