vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { toIsoTimestamp } from "@/types/common";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let detach: () => void;

const orgId = () => tenant.org.id;

function list(actor: Tenant["actors"]["owner"], recipientId: Tenant["userIds"]["owner"], kind?: string[]) {
  return notificationService.listNotifications(actor, {
    orgId: orgId(),
    recipientId,
    unreadOnly: false,
    kind: kind as never,
    limit: 100,
    cursor: null,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("verify", "free");
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("scratch verification", () => {
  it("keeps inboxes and settings personal", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId(), tenant.project.id, { title: "Assigned to viewer", assigneeId: tenant.userIds.viewer }),
    );

    const mine = await list(tenant.actors.viewer, tenant.userIds.viewer, ["issue_assigned"]);
    expect(mine.items).toHaveLength(1);
    expect(mine.items[0]?.href).toBe(`/verify/projects/platform/issues/${issue.number}`);

    await expect(list(tenant.actors.admin, tenant.userIds.viewer)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(list(tenant.actors.owner, tenant.userIds.viewer)).rejects.toBeInstanceOf(PermissionDeniedError);

    const viewerRow = mine.items[0]!;
    await expect(
      notificationService.markRead(tenant.actors.admin, { orgId: orgId(), notificationId: viewerRow.id }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewerBefore = await notificationRepo.countUnread(orgId(), tenant.userIds.viewer);
    expect(viewerBefore).toBe(1);
    await notificationService.markAllRead(tenant.actors.admin, orgId());
    expect(await notificationRepo.countUnread(orgId(), tenant.userIds.viewer)).toBe(viewerBefore);

    await expect(
      notificationService.updatePreference(tenant.actors.member, {
        orgId: orgId(),
        userId: tenant.userIds.viewer,
        kind: "issue_assigned",
        inApp: false,
        email: true,
        digestOnly: false,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await notificationService.markRead(tenant.actors.viewer, { orgId: orgId(), notificationId: viewerRow.id });
    expect(await notificationRepo.countUnread(orgId(), tenant.userIds.viewer)).toBe(0);
  });

  it("alerts the assignee on status change, never the actor, and nothing without an assignee", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(orgId(), tenant.project.id, { title: "Status me", assigneeId: tenant.userIds.viewer }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: orgId(),
      issueId: issue.id,
      status: "in_progress",
    });
    const rows = await list(tenant.actors.viewer, tenant.userIds.viewer, ["issue_status_changed"]);
    expect(rows.items).toHaveLength(1);
    expect(rows.items[0]?.href).toBe(`/verify/projects/platform/issues/${issue.number}`);

    // Board move by the assignee: no self-alert.
    await issueService.moveIssue(tenant.actors.viewer, {
      orgId: orgId(),
      issueId: issue.id,
      toStatus: "done",
      toIndex: 0,
    });
    expect((await list(tenant.actors.viewer, tenant.userIds.viewer, ["issue_status_changed"])).items).toHaveLength(1);

    // Board move by someone else reaches the assignee.
    await issueService.moveIssue(tenant.actors.member, {
      orgId: orgId(),
      issueId: issue.id,
      toStatus: "backlog",
      toIndex: 0,
    });
    expect((await list(tenant.actors.viewer, tenant.userIds.viewer, ["issue_status_changed"])).items).toHaveLength(2);

    // No assignee, no alert.
    const unassigned = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(orgId(), tenant.project.id, { title: "Nobody" }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: orgId(),
      issueId: unassigned.id,
      status: "done",
    });
    expect((await list(tenant.actors.viewer, tenant.userIds.viewer, ["issue_status_changed"])).items).toHaveLength(2);
  });

  it("alerts an assignee set at creation, but not a creator who assigns themselves", async () => {
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId(), tenant.project.id, { title: "Self", assigneeId: tenant.userIds.member }),
    );
    expect((await list(tenant.actors.member, tenant.userIds.member, ["issue_assigned"])).items).toHaveLength(0);
  });

  it("tells the owner about a join, not the person who joined", async () => {
    const member = await memberRepo.findMember(orgId(), tenant.userIds.viewer);
    await emit("member.joined", {
      orgId: orgId(),
      actorId: tenant.userIds.viewer,
      occurredAt: toIsoTimestamp(new Date()),
      memberId: member!.id,
      userId: tenant.userIds.viewer,
      role: "viewer",
    });
    const owner = await list(tenant.actors.owner, tenant.userIds.owner, ["member_joined"]);
    expect(owner.items).toHaveLength(1);
    expect(owner.items[0]?.href).toBe("/verify/settings/members");
    expect((await list(tenant.actors.viewer, tenant.userIds.viewer, ["member_joined"])).items).toHaveLength(0);
  });

  it("alerts the owner once per open refusal, and not on the usage recount", async () => {
    const input = (name: string, key: string) => ({
      orgId: orgId(),
      name,
      slug: name.toLowerCase(),
      key,
      description: null,
      visibility: "org" as const,
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    // Free plan allows two projects; the tenant already has one.
    const second = await projectService.createProject(tenant.actors.admin, input("Second", "SECD"));
    expect(second.slug).toBeTruthy();

    await expect(projectService.createProject(tenant.actors.member, input("Third", "THRD"))).rejects.toThrow();
    const first = await list(tenant.actors.owner, tenant.userIds.owner, ["plan_limit_reached"]);
    expect(first.items).toHaveLength(1);
    expect(first.items[0]?.title).toBe("Plan limit reached: projects");
    expect(first.items[0]?.href).toBe("/verify/settings/billing");

    await expect(projectService.createProject(tenant.actors.member, input("Fourth", "FRTH"))).rejects.toThrow();
    expect((await list(tenant.actors.owner, tenant.userIds.owner, ["plan_limit_reached"])).items).toHaveLength(1);

    await notificationService.markRead(tenant.actors.owner, {
      orgId: orgId(),
      notificationId: first.items[0]!.id,
    });
    await expect(projectService.createProject(tenant.actors.member, input("Fifth", "FFTH"))).rejects.toThrow();
    expect((await list(tenant.actors.owner, tenant.userIds.owner, ["plan_limit_reached"])).items).toHaveLength(2);
    expect((await list(tenant.actors.admin, tenant.userIds.admin, ["plan_limit_reached"])).items).toHaveLength(0);

    await usageService.recomputeUsage(orgId());
    expect((await list(tenant.actors.owner, tenant.userIds.owner, ["plan_limit_reached"])).items).toHaveLength(2);
  });

  it("hides alerts switched off for in-app but still records them", async () => {
    await preferenceRepo.upsertPreference({
      orgId: orgId(),
      userId: tenant.userIds.viewer,
      kind: "issue_assigned",
      inApp: false,
      email: true,
      digestOnly: false,
    });
    const hidden = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId(), tenant.project.id, { title: "Hidden", assigneeId: tenant.userIds.viewer }),
    );
    const inbox = await list(tenant.actors.viewer, tenant.userIds.viewer, ["issue_assigned"]);
    expect(inbox.items.some((row) => row.href.endsWith(`/issues/${hidden.number}`))).toBe(false);
    expect(await notificationRepo.countUnread(orgId(), tenant.userIds.viewer)).toBe(0);

    const raw = await notificationRepo.listUnreadSince(orgId(), tenant.userIds.viewer, toIsoTimestamp(new Date(0)));
    expect(raw.some((row) => row.href.endsWith(`/issues/${hidden.number}`) && row.channels.includes("email"))).toBe(true);
  });

  it("pages through every in-app alert exactly once", async () => {
    for (let i = 0; i < 7; i += 1) {
      await notificationService.notify(orgId(), "comment_created", [tenant.userIds.admin], {
        title: `N${i}`,
        body: "b",
        href: "/x",
        actorId: null,
      });
    }
    const seen: string[] = [];
    let cursor: string | null = null;
    let total = -1;
    do {
      const page = await notificationService.listNotifications(tenant.actors.admin, {
        orgId: orgId(),
        recipientId: tenant.userIds.admin,
        unreadOnly: false,
        limit: 3,
        cursor,
      });
      seen.push(...page.items.map((row) => row.id));
      total = page.total;
      cursor = page.nextCursor;
    } while (cursor !== null);

    expect(new Set(seen).size).toBe(seen.length);
    expect(seen.length).toBe(total);
    expect(total).toBe(7);
  });

  it("links search hits for issues, comments and projects", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId(), tenant.project.id, { title: "Zebra unique term" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: orgId(),
      issueId: issue.id,
