    const commentHit = hits.items.find((hit) => hit.kind === "comment");
    expect(issueHit?.href).toBe(`/verify/projects/platform/issues/${issue.number}`);
    expect(commentHit?.href).toBe(`/verify/projects/platform/issues/${issue.number}`);

    const projects = await searchService.search(tenant.actors.member, {
      orgId: orgId(),
      q: "Second",
      kinds: ["project"],
      limit: 25,
      cursor: null,
    });
    expect(projects.items[0]?.href).toBe("/verify/projects/second");
  });
